/* The personalised, voice-first demo experience. */
let profile={name:'Alex Johnson',standard:'My apprenticeship'},requirements=seedK.map(k=>({...k,base:0,target:5})),targets=[],setupRows=[],setupProblem='',setupKind='ksb',workspaceLoaded=false,hasPersonalRequirements=false,conversationStage='work',chatText='',reflection='',recognition=null,listening=false,voiceError='',speakReplies=false;
const today='2026-10-03';
icons.mic='<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/>';
const robot=cls=>`<img class="buddy-robot ${cls||''}" src="buddy.png" alt="Buddy, your friendly little robot">`;
function sortedRequirements(){return [...requirements].sort((a,b)=>{const group=c=>({K:0,S:1,B:2}[c[0]]??3);return group(a.code)-group(b.code)||a.code.localeCompare(b.code,undefined,{numeric:true})})}
applyRecords=function(){logs=(demoMode?[...savedRecords,...seedLogs.map(l=>({...l,demo:true}))]:[...savedRecords]).sort((a,b)=>b.date.localeCompare(a.date));ksbs=sortedRequirements().map(k=>({...k,base:demoMode?(seedK.find(s=>s.code===k.code)?.base||0):0}));};
async function persistSettings(){const r=await fetch('/api/settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({profile,requirements,targets,hasPersonalRequirements})});if(!r.ok)throw Error('Couldn’t save your requirements. Your preview is still here; try again.');}
loadRecords=async function(){try{const [r,s]=await Promise.all([fetch('/api/records'),fetch('/api/settings')]);if(!r.ok||!s.ok)throw Error();savedRecords=await r.json();const settings=await s.json();if(settings.profile)profile=settings.profile;if(settings.requirements?.length)requirements=settings.requirements;if(settings.targets)targets=settings.targets;hasPersonalRequirements=!!settings.hasPersonalRequirements;workspaceLoaded=true;applyRecords();storageError='';render()}catch{storageError='Couldn’t load your saved workspace. Your current input is preserved. Please refresh when the local server is running.';render()}};
function speak(text){if(!speakReplies||!window.speechSynthesis)return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-GB';u.rate=1;window.speechSynthesis.speak(u)}
function followup(){const w=draft.work.toLowerCase();if(/present|meeting|team|manager|colleague/.test(w))return 'Nice! What did you learn from the conversation, or what feedback did you get?';if(/report|data|analys|figures/.test(w))return 'Sounds like a useful day. What did you discover, and how did you check your findings?';return 'Nice, tell me a little more — what did you learn, and what would you do differently next time?'}
makeSuggestions=function(){const work=draft.work.toLowerCase(),combined=(draft.work+' '+(draft.reflection||'')).toLowerCase();const ignore=new Set(['with','from','your','their','this','that','have','work','understanding','ability','demonstrate','knowledge','skills','using','used','into','them','were','been','will','about','information']);const terms=t=>[...new Set(t.toLowerCase().match(/[a-z]{4,}/g)||[])].filter(w=>!ignore.has(w));const synonyms=[[/report|power bi|sales|finance|discrepanc|analys/,['analyse','data','report','interpret','quality','validation']],[/manager|process|business/,['business','process','responsibility']],[/team|colleague|meeting|spoke/,['collaborat','communication','others']],[/present|stakeholder/,['present','stakeholder','communication']],[/privacy|personal|protect/,['protection','ethic','privacy']],[/statistic|regression|average/,['statistic','technique']],[/clean|import|collect|organis/,['collect','organise','quality']]];suggestions=ksbs.map(k=>{const keywords=terms(k.title+' '+(k.description||''));let score=keywords.filter(t=>combined.includes(t)||combined.includes(t.replace(/ing$/,''))).length;synonyms.forEach(([pattern,words])=>{if(pattern.test(combined)&&words.some(word=>keywords.some(t=>t.includes(word))))score++});return {k,score}}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,4).map(({k})=>({id:k.code,reason:`Your activity may connect to “${k.title}”. Check that your work and reflection demonstrate this requirement, and attach a specific output or feedback to support it.`,confidence:'Suggested connection',accepted:false}));draft.title=draft.work.trim().split(/[.!?]/)[0].slice(0,80);draft.summary=draft.work.trim();draft.learn=draft.reflection?.trim()||'Add what you learned or understood better before saving.'};
function targetTracker(t){const current=Number(t.current||0),goal=Number(t.target||0),pct=goal>0?Math.min(100,Math.round(current/goal*100)):0;return `<div class="target-tracker"><div><b>${esc(t.title)}</b><span>${current} / ${goal} ${esc(t.unit||'')}</span></div><div class="bar"><div class="fill" style="width:${pct}%"></div></div><small>${t.type==='kpi'?'KPI':'Objective'} · imported values</small></div>`}
dashboard=function(){const own=logs.filter(l=>!l.demo);return `<section class="buddy-home"><div class="buddy-welcome"><div class="eyebrow">A LITTLE CHAT. A CLEARER PICTURE.</div><h1>Hey ${esc(profile.name.split(' ')[0])}. Let’s talk about your day.</h1><p>No perfect words needed. That’s what your Buddy is here for.</p></div><div class="buddy-layout"><div class="buddy-conversation"><div class="voice-stage">${robot('hero-robot')}<div class="buddy-intro"><span class="buddy-name">YOUR WORK BUDDY</span><h2>${conversationStage==='reflection'?'What clicked for you today?':'Big day? Little wins? I’m listening.'}</h2><p>${conversationStage==='reflection'?esc(followup()):'Tell me what you worked on. We’ll turn it into a record of your learning, together.'}</p></div></div><div id="messages" aria-live="polite">${buddyMessages.map(m=>`<div class="chat-message ${m.who}"><span>${m.who==='you'?'You':'Buddy'}</span><p>${esc(m.text)}</p></div>`).join('')}</div><div class="voice-controls"><button class="voice-button ${listening?'listening':''}" id="voice-button" type="button" aria-label="${listening?'Stop recording':'Talk to Buddy using your microphone'}">${icon('mic')}</button><div><b id="voice-status">${listening?'I’m listening… tap to stop':'Tap to talk to Buddy'}</b><span>Or type below. You can edit the transcript.</span></div></div>${voiceError?`<p class="voice-error" role="status">${esc(voiceError)}</p>`:''}<form id="personal-chat-form"><label class="sr-only" for="chat-text">${conversationStage==='reflection'?'What did you learn?':'Tell Buddy about your day'}</label><textarea id="chat-text" rows="3" minlength="10" required placeholder="${conversationStage==='reflection'?'I learned that…':'Today I worked on…'}">${esc(chatText)}</textarea><div class="composer-bottom"><span>${conversationStage==='reflection'?'Your learning, in your own words.':'Just tell me the messy version.'}</span><button class="btn primary" type="submit">${conversationStage==='reflection'?'Review my record':'Send to Buddy'} ${icon('spark')}</button></div>${conversationStage==='work'?`<details class="capture-extras"><summary>Time, date & evidence</summary><div class="form-grid"><div><label for="capture-hours">Learning time (hours)</label><input id="capture-hours" type="number" min="0.25" max="24" step="0.25" value="${draft?.hours||1}"></div><div><label for="capture-date">Date</label><input id="capture-date" type="date" value="${draft?.date||today}" max="${today}" required></div><div><label for="capture-project">Project / category</label><input id="capture-project" value="${esc(draft?.project||'Daily learning')}"></div></div><label class="checkline"><input id="capture-otj" type="checkbox" ${draft?.otj?'checked':''}> This included off-the-job learning</label><label for="capture-files" style="margin-top:18px">Evidence references (filenames only)</label><input id="capture-files" type="file" multiple></details>`:''}</form><div class="conversation-settings"><label class="checkline"><input id="speak-replies" type="checkbox" ${speakReplies?'checked':''}> Buddy speaks back</label><span>Simulated suggestions · always yours to review</span></div><p class="speech-note">Voice uses your browser’s speech recognition service. Audio may be processed by its provider; ks-buddy stores the text you save, not audio.</p>${draft?.summary?`<div class="buddy-review"><h3>Your conversation is ready to review.</h3><p>Check your learning and ${suggestions.length} suggested connections before saving.</p>${btn('Review my record','analysis',true)} <button class="text-link" data-buddy="new">Start another chat</button></div>`:''}${storageError?`<div class="notice">${esc(storageError)}</div>`:''}</div><aside class="buddy-trackers"><div class="trackers-head"><h2>Your learning, taking shape</h2><span>${esc(profile.standard)}</span></div><div class="simple-metrics"><div><b>${own.length}</b><span>activities captured</span></div><div><b>${own.filter(l=>l.otj).reduce((s,l)=>s+l.hours,0)}<em>h</em></b><span>off-the-job learning</span></div></div><div class="coverage-inline"><div><span>Evidence coverage</span><b>${avg()}%</b></div><div class="bar"><div class="fill" style="width:${avg()}%"></div></div><small>${ksbs.filter(k=>progress(k)>0).length} of ${ksbs.length} requirements have activity references</small></div><div class="compact-ksbs">${ksbs.map(k=>`<a href="#ksb/${encodeURIComponent(k.code)}"><div>${code(k.code)}<span>${esc(k.title)}</span></div>${bar(k)}<small>${mapped(k).length} evidence activit${mapped(k).length===1?'y':'ies'} · ${mapped(k).reduce((s,l)=>s+l.files.length,0)} references</small></a>`).join('')}</div><a class="text-link" href="#progress">Explore evidence & gaps</a>${targets.length?`<section class="targets-section"><h3>Your objectives & KPIs</h3>${targets.map(targetTracker).join('')}</section>`:''}<div class="tracker-guidance"><h3>Made for your apprenticeship.</h3><p>${requirements===seedK?'':'Upload your own requirements, objectives or KPIs whenever you’re ready.'}</p><a href="#import" class="text-link">Add your data</a></div></aside></div><section class="buddy-recent"><div class="card-head"><h2>Your recent learning</h2><a href="#history" class="text-link">View your history</a></div>${own.length?own.slice(0,3).map(activity).join(''):'<p class="muted">Start a conversation or import your previous reports. Your story will appear here.</p>'}</section></section>`};
function voiceUpdate(){const status=$('#voice-status');if(status)status.textContent=listening?'I’m listening… tap to stop':'Tap to talk to Buddy';const b=$('#voice-button');if(b){b.classList.toggle('listening',listening);b.setAttribute('aria-label',listening?'Stop recording':'Talk to Buddy using your microphone')}}
function toggleVoice(){if(listening&&recognition){recognition.stop();return}const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){voiceError='Voice transcription isn’t available in this browser. Open this page in Chrome or Edge, or type your message below.';render();return}voiceError='';if(window.speechSynthesis)window.speechSynthesis.cancel();recognition=new SR();recognition.lang='en-GB';recognition.continuous=true;recognition.interimResults=true;const prefix=chatText.trim();let final='';recognition.onstart=()=>{listening=true;voiceUpdate()};recognition.onresult=e=>{let interim='';for(let i=e.resultIndex;i<e.results.length;i++){if(e.results[i].isFinal)final+=e.results[i][0].transcript+' ';else interim+=e.results[i][0].transcript}chatText=[prefix,final,interim].filter(Boolean).join(' ').trim();if($('#chat-text'))$('#chat-text').value=chatText};recognition.onerror=e=>{voiceError=({'not-allowed':'Microphone access was declined. Allow it in your browser settings, or type below.','audio-capture':'No microphone is available. Connect one or type below.','network':'Your browser’s speech service couldn’t connect. Please type your entry for now.','no-speech':'I didn’t catch that. Tap the microphone to try again.'})[e.error]||'Voice capture stopped. Your transcript is still here.';listening=false;render()};recognition.onend=()=>{listening=false;voiceUpdate()};try{recognition.start()}catch{voiceError='Voice capture couldn’t start. You can still type below.';render()}}
function stopVoice(){if(recognition&&listening)recognition.stop();listening=false}
function clearConversation(){stopVoice();draft=null;suggestions=[];buddyMessages=[];chatText='';reflection='';conversationStage='work';editing=null;render()}
const previousSave=saveRecord;saveRecord=async function(selected){await previousSave(selected);if(!draft){chatText='';reflection='';conversationStage='work';render()}};
const priorAnalysis=analysisPage;analysisPage=function(){return priorAnalysis()+ (draft?`<div class="narrow"><section class="manual-mapping"><label for="extra-ksb">Add another requirement to review</label><div class="buttons"><select id="extra-ksb">${ksbs.filter(k=>!suggestions.some(s=>s.id===k.code)).map(k=>`<option value="${esc(k.code)}">${esc(k.code)} · ${esc(k.title)}</option>`).join('')}</select><button class="btn" data-buddy="add-ksb" ${ksbs.every(k=>suggestions.some(s=>s.id===k.code))?'disabled':''}>Add mapping</button></div></section></div>`:'')};
function normalizeRequirements(rows,kind){if(!rows.length||rows.length>300)throw Error('Choose a CSV with between 1 and 300 rows.');const ids=new Set();return rows.map((r,i)=>{const pick=(...keys)=>{for(const key of keys)if(r[key]!==undefined&&String(r[key]).trim())return String(r[key]).trim();return ''};const id=pick('code','ksb_code','ksb','id')||(kind==='ksb'?'':`${kind.toUpperCase()}${i+1}`),title=pick('title','description','requirement','objective','kpi','name');if(!id||!title)throw Error(`Row ${i+1}: include code and description for KSBs, or a title for objectives/KPIs.`);if(!/^[A-Za-z0-9_.-]{1,30}$/.test(id)||ids.has(id))throw Error(`Row ${i+1}: codes must be unique, using letters, numbers, dots, dashes or underscores (up to 30 characters).`);ids.add(id);const target=Number(pick('target','target_value','evidence_target')||(kind==='ksb'?5:0)),current=Number(pick('current','current_value','value')||0);if(!Number.isFinite(target)||target<=0||!Number.isFinite(current)||current<0)throw Error(`Row ${i+1}: target must be a positive number and current must be zero or more.`);return kind==='ksb'?{code:id,title,description:pick('description','requirement')||title,target,base:0}:{id,title,type:kind,target,current,unit:pick('unit')};})}
const activityImportPage=importPage;importPage=function(){const activity=activityImportPage();return `<div class="narrow">${head('Your apprenticeship. Your data.','Add your requirements and targets, then bring your past learning into Buddy.','','YOUR WORKSPACE')}<form id="profile-form" class="profile-form"><div><label for="profile-name">Your name</label><input id="profile-name" value="${esc(profile.name)}" required></div><div><label for="profile-standard">Apprenticeship</label><input id="profile-standard" value="${esc(profile.standard)}" required></div><button type="submit" class="btn">Save details</button></form><section class="requirements-import"><h2>Requirements, objectives & KPIs</h2><p class="subtitle">Choose what you’re uploading. Preview it before it becomes part of your workspace.</p><div class="import-options">${[['ksb','KSB requirements'],['objective','Objectives'],['kpi','KPIs']].map(([id,t])=>`<button type="button" class="tab ${setupKind===id?'active':''}" data-buddy-kind="${id}">${t}</button>`).join('')}</div><label for="setup-file">${setupKind==='ksb'?'KSB requirements':setupKind==='kpi'?'KPIs':'Objectives'} CSV</label><input type="file" id="setup-file" accept=".csv,text/csv"><p class="hint">${setupKind==='ksb'?'Columns: code, description, target (optional number of evidence activities; defaults to 5).':'Columns: title, target, current (optional), unit (optional). Imported numeric values power these trackers.'}</p><button class="text-link" data-buddy="requirements-template">Download ${setupKind==='ksb'?'requirements':setupKind} example</button>${setupProblem?`<p class="error" role="alert">${esc(setupProblem)}</p>`:''}${setupRows.length?`<div class="upload-preview"><h3>Preview · ${setupRows.length} rows</h3>${setupRows.map(r=>`<div><b>${esc(r.code||r.id)}</b><span>${esc(r.title)}</span><small>Target: ${r.target}${r.type?' · Current: '+r.current+' '+esc(r.unit):' evidence activities'}</small></div>`).join('')}<p class="hint">Your first upload replaces the starter requirements. Later uploads update matching codes. Saved history is kept.</p><button class="btn primary" data-buddy="save-requirements">Add to my workspace</button></div>`:''}</section></div><div class="history-import">${activity.replace(head('Bring your work into Buddy.','Import activities from another tool, then review what belongs in your record.','','IMPORT DATA'),'<h2>Import your previous reports</h2><p class="subtitle">Past activity and today’s conversation build the same personal record.</p>')}</div>`};
progressPage=function(){return head('Your evidence, one requirement at a time.','See what’s covered and find a useful next step.',btn('Talk to Buddy','dashboard',true),'PROGRESS & GAPS')+`<div class="gap-grid">${[['Going well','A useful range of supporting activities.',k=>state(k)==='strong'],['Building your evidence','Try a fresh context or add supporting references.',k=>['progressing','attention'].includes(state(k))],['Not covered yet','A starting point for your next conversation.',k=>state(k)==='empty']].map(([t,p,fn])=>`<section class="card"><h2>${t} <span class="badge">${ksbs.filter(fn).length}</span></h2><p class="subtitle">${p}</p>${ksbs.filter(fn).map(row).join('')||'<p class="hint section-space">Nothing here right now.</p>'}</section>`).join('')}</div><section class="section-space"><h2>Suggested next steps</h2><div class="opportunities">${ksbs.filter(k=>state(k)!=='strong').slice(0,4).map(k=>`<section class="card"><div class="row-top">${code(k.code)}</div><h3>${esc(k.title)}</h3><p class="subtitle">Look for a task where you can demonstrate this requirement in a new context. Ask your manager for an opportunity, then tell Buddy what you did and learned.</p>${btn('View evidence','ksb/'+encodeURIComponent(k.code))}</section>`).join('')}</div></section>`};
const oldDetail=detailPage;detailPage=function(id){return oldDetail(decodeURIComponent(id||''))};
const innerRender=render;render=function(){if(!sessionStorage.getItem('ks-buddy-demo-session')){$('#nav').innerHTML='';$('#breadcrumb').textContent='Welcome to ks-buddy';$('#app').innerHTML=`<div class="demo-entry">${robot('login-robot')}<div class="eyebrow">MEET YOUR NEW WORK BUDDY</div><h1>A little chat.<br>A clearer picture.</h1><p>Talk about your day. Find the learning.<br>Build your apprenticeship story.</p><button class="btn primary" id="enter-demo">Enter demo workspace</button><small>One demo apprentice · no password needed</small></div>`;$('#enter-demo').onclick=()=>{sessionStorage.setItem('ks-buddy-demo-session','1');render()};return}innerRender();const profileEl=$('.profile');if(profileEl)profileEl.innerHTML=`<span class="avatar">${esc(profile.name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</span><div>${esc(profile.name)}<small>Apprentice · Demo account</small></div>`;const ws=$('.workspace');if(ws)ws.innerHTML=`<span class="workspace-icon">${icon('target')}</span><div>My apprenticeship<small>${esc(profile.standard)}</small></div>`;$('#nav').innerHTML=[['dashboard','Talk to Buddy','mic'],['progress','My progress','progress'],['history','My evidence','file'],['report','Reports','report'],['import','My requirements','target']].map(([r,t,i])=>`<a href="#${r}" class="${(location.hash.slice(1)||'dashboard')===r?'active':''}">${icon(i)}${t}</a>`).join('')};
const olderBind=bindForms;bindForms=function(){olderBind();if($('#chat-text'))$('#chat-text').oninput=e=>chatText=e.target.value;if($('#voice-button'))$('#voice-button').onclick=toggleVoice;if($('#speak-replies'))$('#speak-replies').onchange=e=>{speakReplies=e.target.checked;if(!speakReplies&&window.speechSynthesis)window.speechSynthesis.cancel()};if($('#personal-chat-form'))$('#personal-chat-form').onsubmit=e=>{e.preventDefault();stopVoice();const text=chatText.trim();if(text.length<10)return;buddyMessages.push({who:'you',text});if(conversationStage==='work'){draft={work:text,date:$('#capture-date').value,hours:Number($('#capture-hours').value),project:$('#capture-project').value||'Daily learning',otj:$('#capture-otj').checked,files:[...$('#capture-files').files].map(f=>f.name)};conversationStage='reflection';chatText='';const reply=followup();buddyMessages.push({who:'buddy',text:reply});render();speak(reply)}else{reflection=text;draft.reflection=text;makeSuggestions();chatText='';conversationStage='work';buddyMessages.push({who:'buddy',text:`That’s useful learning. I’ve put together your activity and ${suggestions.length} possible KSB connections. Let’s review them together.`});location.hash='analysis'}};if($('#setup-file'))$('#setup-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2000000)throw Error('Choose a CSV smaller than 2 MB.');setupRows=normalizeRequirements(parseCSV(await f.text()),setupKind);setupProblem='';render()}catch(err){setupRows=[];setupProblem=err.message;render()}};if($('#profile-form'))$('#profile-form').onsubmit=async e=>{e.preventDefault();const old=profile;profile={name:$('#profile-name').value.trim(),standard:$('#profile-standard').value.trim()};try{await persistSettings();render();toast('Your details have been saved.')}catch(err){profile=old;toast(err.message)}}};
function downloadCSV(content,name){const u=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)}
document.addEventListener('click',async e=>{const kind=e.target.closest('[data-buddy-kind]');if(kind){setupKind=kind.dataset.buddyKind;setupRows=[];setupProblem='';render();return}const b=e.target.closest('[data-buddy]');if(!b)return;const action=b.dataset.buddy;if(action==='new')clearConversation();if(action==='add-ksb'){syncAnalysis();const id=$('#extra-ksb').value;if(id&&!suggestions.some(s=>s.id===id)){suggestions.push({id,reason:'Explain how your activity supports this requirement.',accepted:false,confidence:'Added by you'});render()}}if(action==='requirements-template')downloadCSV(setupKind==='ksb'?'code,description,target\nK1,Understand business processes,5\nS1,Collect and organise data,5\nB1,Collaborate with others,5\n':'title,target,current,unit\n'+(setupKind==='kpi'?'Learning hours,30,8,hours\n':'Complete project reflections,4,1,reflections\n'),`ks-buddy-${setupKind}-example.csv`);if(action==='save-requirements'){b.disabled=true;const prevReq=requirements,prevTargets=targets,prevCustom=hasPersonalRequirements;const merge=(old,rows,key)=>{const m=new Map(old.map(r=>[r[key],r]));rows.forEach(r=>m.set(r[key],r));return [...m.values()]};if(setupKind==='ksb'){requirements=merge(hasPersonalRequirements?requirements:[],setupRows,'code');hasPersonalRequirements=true;}else targets=merge(targets,setupRows,'id');try{await persistSettings();setupRows=[];setupProblem='';applyRecords();render();toast('Your workspace now tracks your uploaded data.')}catch(err){requirements=prevReq;targets=prevTargets;hasPersonalRequirements=prevCustom;setupProblem=err.message;render()}}});
window.addEventListener('hashchange',()=>{stopVoice();if(window.speechSynthesis)window.speechSynthesis.cancel()});

let rawHistory=[],historyHeaders=[],historyMapping={};
const importWithSettings=importPage;importPage=function(){return importWithSettings()+ (rawHistory.length?`<div class="narrow"><section class="column-mapper"><h2>Match your history columns</h2><p class="subtitle">Choose the fields in your CSV. This works even when the export uses different column names.</p><div class="mapping-fields">${[['date','Activity date'],['work','Day / activity transcript'],['learn','Learning / reflection'],['hours','Hours'],['project','Project / category'],['codes','KSB codes'],['otj','Off-the-job verdict'],['files','Evidence references']].map(([key,label])=>`<div><label for="map-${key}">${label}${['date','work'].includes(key)?' *':''}</label><select id="map-${key}" data-column="${key}"><option value="">${['date','work'].includes(key)?'Choose a column':'Not supplied'}</option>${historyHeaders.map(h=>`<option value="${esc(h)}" ${historyMapping[key]===h?'selected':''}>${esc(h)}</option>`).join('')}</select></div>`).join('')}</div><button class="btn primary" data-buddy="preview-history">Preview mapped activities</button><p class="hint">Dates must be YYYY-MM-DD. Off-the-job “counts” is included; “check” and “needs info” remain excluded pending review.</p></section></div>`:'')};
const fullBind=bindForms;bindForms=function(){fullBind();if($('#import-file'))$('#import-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error('Choose a file smaller than 2 MB.');const text=await file.text();const parsed=file.name.toLowerCase().endsWith('.json')?JSON.parse(text):parseCSV(text);rawHistory=Array.isArray(parsed)?parsed:parsed.activities||parsed.records;if(!Array.isArray(rawHistory)||!rawHistory.length)throw Error('No activities found.');historyHeaders=[...new Set(rawHistory.flatMap(r=>Object.keys(r)))];const aliases={date:['date','activity_date','day_date','log_date'],work:['work','description','activity','notes','text','transcript','daily_log','day_log','log'],learn:['learn','learning','reflection','what_learned'],hours:['hours','learning_hours','time_spent'],project:['project','category'],codes:['codes','ksbs','ksb_codes'],otj:['otj','off_the_job','otj_verdict','verdict'],files:['files','evidence','attachments']};historyMapping=Object.fromEntries(Object.entries(aliases).map(([k,opts])=>[k,opts.find(h=>historyHeaders.includes(h))||'']));importItems=[];importProblem='';render()}catch(err){rawHistory=[];importProblem=err.message;render()}}};
document.addEventListener('click',e=>{if(!e.target.closest('[data-buddy="preview-history"]'))return;try{historyMapping=Object.fromEntries([...document.querySelectorAll('[data-column]')].map(el=>[el.dataset.column,el.value]));if(!historyMapping.date||!historyMapping.work)throw Error('Choose your date and transcript columns.');const rows=rawHistory.map(r=>Object.fromEntries(Object.entries(historyMapping).filter(([,h])=>h).map(([k,h])=>[k,r[h]])));importItems=normaliseImport(rows);importProblem='';render();document.querySelector('[data-import="save"]')?.scrollIntoView({block:'center',behavior:'smooth'})}catch(err){importProblem=err.message;render()}});
window.addEventListener('hashchange',()=>render());
render();loadRecords();
